#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn basic() {
        assert_eq!(ListNode::to_vec(&reverse_list(ListNode::from_vec(&[1, 2, 3]))), vec![3, 2, 1]);
    }

    #[test]
    fn two_nodes() {
        assert_eq!(ListNode::to_vec(&reverse_list(ListNode::from_vec(&[7, 8]))), vec![8, 7]);
    }

    #[test]
    fn single_and_empty() {
        assert_eq!(ListNode::to_vec(&reverse_list(ListNode::from_vec(&[5]))), vec![5]);
        assert_eq!(reverse_list(None), None);
    }

    #[test]
    fn in_place() {
        let head = ListNode::from_vec(&[1, 2, 3, 4]);
        let first = head.as_deref().unwrap() as *const ListNode;
        let tail = {
            let mut cur = head.as_deref().unwrap();
            while let Some(n) = cur.next.as_deref() {
                cur = n;
            }
            cur as *const ListNode
        };
        let new_head = reverse_list(head);
        // The old tail node must now be the head, and the old head the tail.
        assert_eq!(new_head.as_deref().unwrap() as *const ListNode, tail);
        let mut cur = new_head.as_deref().unwrap();
        while let Some(n) = cur.next.as_deref() {
            cur = n;
        }
        assert_eq!(cur as *const ListNode, first);
        assert_eq!(ListNode::to_vec(&new_head), vec![4, 3, 2, 1]);
    }
}
